暴力只需要正确，不需要快，直接用 cin 读入、cout 输出，gen 会替它做重定向
骨架如下
#include using namespace std; int main() { // 读入用 cin, 输出用 cout, 不要 freopen } 以 lamp 为例，用 O(n^2) 的 DP 枚举最后一段的起点
// O(n^2) 枚举最后一段的起点做 DP; 中位数为1 <=> 1 的个数 >= ceil(len/2) #include using namespace std; int main() { int n; cin >> n; vector<int> s(n + 1), mx(n + 1, 0), mn(n + 1, 1e9); for (int i = 1; i <= n; i++) { cin >> s[i]; s[i] += s[i - 1]; // 前缀和: 1 的个数 } mn[0] = 0; for (int i = 1; i <= n; i++) { for (int j = 0; j < i; j++) { int lit = 2 * (s[i] - s[j]) >= i - j; // 段 (j, i] 的指示灯是否点亮 mx[i] = max(mx[i], mx[j] + lit); mn[i] = min(mn[i], mn[j] + lit); } } cout << mx[n] << " " << mn[n] << endl; }

